-- "Roland - SR-JV80-04 Vintage Synths" (with trailing 's') vs existing
-- "SR-JV80-04 Vintage Synth" preserved as separate product per verbatim.

INSERT OR IGNORE INTO manufacturers (name) VALUES
  ('Sampleheads'),
  ('AMG');

INSERT OR IGNORE INTO products (manufacturer_id, name, type) VALUES
